export type EnumName = keyof typeof enumValues;
/** The literal values the pinned specification knows for an enum. */
export type KnownEnumValue<N extends EnumName> = (typeof enumValues)[N][number];
/** Known values of a generated enum, in specification order. */
export function knownEnumValues<N extends EnumName>(name: N): (typeof enumValues)[N] { return enumValues[name]; }
/** True when `value` is one of the enum's pinned values; false for an unknown (newer upstream) value. */
export function isKnownEnumValue<N extends EnumName>(name: N, value: unknown): value is KnownEnumValue<N> { return (enumValues[name] as readonly unknown[]).includes(value); }
